  // NEW EXAM STATE CHUẨN IDP
  const [examTheme, setExamTheme] = useState<'default'|'dark'|'yellow'>('default');
  const [examTextSize, setExamTextSize] = useState<'standard'|'large'|'xlarge'>('standard');
